1	package server
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"math/big"
7		"net/http"
8		"sort"
9	)
10	
11	// Error code reported when the plan request envelope or the prior state
12	// document is structurally invalid.
13	const codeInvalidPlanRequest = "invalid_plan_request"
14	
15	// planSnapshot is the normalized view of one resource at one side of a
16	// change: before for the prior state, after for the configuration. It is an
17	// alias of the exported Snapshot handed to Provider implementations so that
18	// the read-only plan endpoint and the apply endpoint share one shape.
19	type planSnapshot = Snapshot
20	
21	// planChange is one planned action. Create carries only After, delete only
22	// Before, update carries both.
23	type planChange struct {
24		Address string        `json:"address"`
25		Action  string        `json:"action"`
26		Before  *planSnapshot `json:"before,omitempty"`
27		After   *planSnapshot `json:"after,omitempty"`
28	}
29	
30	type planSummary struct {
31		Create int `json:"create"`
32		Update int `json:"update"`
33		Delete int `json:"delete"`
34		Noop   int `json:"noop"`
35	}
36	
37	type planResponse struct {
38		Valid   bool              `json:"valid"`
39		Errors  []validationError `json:"errors"`
40		Changes []planChange      `json:"changes"`
41		Summary planSummary       `json:"summary"`
42	}
43	
44	// planResource is the plan-relevant view of one resource, extracted from an
45	// already-validated configuration or prior state document.
46	type planResource struct {
47		address    string
48		typ        string
49		properties map[string]any
50		dependsOn  []string
51	}
52	
53	// handlePlanConfiguration computes the diff between a desired configuration
54	// and a prior state. It only computes the plan; nothing is applied or
55	// persisted.
56	func handlePlan(w http.ResponseWriter, r *http.Request) {
57		w.Header().Set("Content-Type", "application/json; charset=utf-8")
58		if r.Method != http.MethodPost {
59			rejectMethodNotAllowed(w)
60			return
61		}
62	
63		changes, summary, _, ok := preparePlan(w, r)
64		if !ok {
65			return
66		}
67	
68		w.WriteHeader(http.StatusOK)
69		_ = json.NewEncoder(w).Encode(planResponse{
70			Valid:   true,
71			Errors:  []validationError{},
72			Changes: changes,
73			Summary: summary,
74		})
75	}
76	
77	// preparePlan runs the request through the same pipeline the read-only plan
78	// endpoint uses: decode the body, validate the envelope, configuration,
79	// dependencies and prior state, then compute the ordered diff. On any client
80	// failure it writes the 400/422 response itself and returns ok=false, so the
81	// caller never invokes a Provider for an invalid request. On success it also
82	// returns the validated prior-state resources, used to seed the resulting
83	// state of an apply run.
84	func preparePlan(w http.ResponseWriter, r *http.Request) (changes []planChange, summary planSummary, stateResources []planResource, ok bool) {
85		doc, ok := decodeConfigurationBody(w, r)
86		if !ok {
87			return nil, planSummary{}, nil, false
88		}
89	
90		configRaw, stateRaw, ok := checkPlanEnvelope(w, doc)
91		if !ok {
92			return nil, planSummary{}, nil, false
93		}
94	
95		// Configuration and prior state are validated independently; their
96		// findings are merged and sorted together. Configuration findings keep
97		// their codes and gain a /configuration path prefix. The configuration
98		// is planned from its variable-resolved view, so snapshots, state, and
99		// Provider requests only ever carry literal properties.
100		var errs []validationError
101		var configResources []planResource
102		var configOrder []string
103		if resolved, baseErrs := resolveConfiguration(configRaw); len(baseErrs) != 0 {
104			errs = appendPrefixedErrors(errs, baseErrs, "/configuration")
105		} else if order, depErrs := orderConfiguration(configRaw); len(depErrs) != 0 {
106			errs = appendPrefixedErrors(errs, depErrs, "/configuration")
107		} else {
108			configResources = configurationResources(resolved)
109			configOrder = order
110		}
111	
112		stateResources, stateOrder, stateErrs := checkPriorState(stateRaw)
113		errs = append(errs, stateErrs...)
114	
115		if len(errs) != 0 {
116			sortValidationErrors(errs)
117			writeValidation(w, http.StatusUnprocessableEntity, errs)
118			return nil, planSummary{}, nil, false
119		}
120	
121		changes, summary = computePlan(configResources, configOrder, stateResources, stateOrder)
122		return changes, summary, stateResources, true
123	}
124	
125	// rejectMethodNotAllowed writes the shared 405 response for the POST-only
126	// planning and apply endpoints: Allow: POST and a method_not_allowed code.
127	func rejectMethodNotAllowed(w http.ResponseWriter) {
128		w.Header().Set("Allow", http.MethodPost)
129		w.WriteHeader(http.StatusMethodNotAllowed)
130		_ = json.NewEncoder(w).Encode(map[string]any{
131			"error": map[string]string{"code": "method_not_allowed"},
132		})
133	}
134	
135	// checkPlanEnvelope validates the request envelope: a JSON object holding
136	// exactly the configuration and priorState fields. On failure it writes the
137	// 422 response and returns ok=false.
138	func checkPlanEnvelope(w http.ResponseWriter, doc any) (configuration, priorState any, ok bool) {
139		var errs []validationError
140		add := func(code, message, path string) {
141			errs = append(errs, validationError{Code: code, Message: message, Path: path})
142		}
143	
144		root, isObject := doc.(map[string]any)
145		if !isObject {
146			add(codeInvalidPlanRequest, "request body must be a JSON object", "")
147		} else {
148			for key := range root {
149				if key != "configuration" && key != "priorState" {
150					add(codeInvalidPlanRequest, fmt.Sprintf("unknown field %q", key), "/"+pointerEscape(key))
151				}
152			}
153			var hasConfig, hasState bool
154			configuration, hasConfig = root["configuration"]
155			priorState, hasState = root["priorState"]
156			if !hasConfig {
157				add(codeInvalidPlanRequest, `missing required field "configuration"`, "")
158			}
159			if !hasState {
160				add(codeInvalidPlanRequest, `missing required field "priorState"`, "")
161			}
162		}
163	
164		if len(errs) != 0 {
165			sortValidationErrors(errs)
166			writeValidation(w, http.StatusUnprocessableEntity, errs)
167			return nil, nil, false
168		}
169		return configuration, priorState, true
170	}
171	
172	// appendPrefixedErrors appends errs to dst with every path rooted at prefix,
173	// so findings from an embedded document point into the request envelope.
174	func appendPrefixedErrors(dst []validationError, errs []validationError, prefix string) []validationError {
175		for _, e := range errs {
176			e.Path = prefix + e.Path
177			dst = append(dst, e)
178		}
179		return dst
180	}
181	
182	// configurationResources extracts the plan-relevant view of an
183	// already-validated configuration document.
184	func configurationResources(doc any) []planResource {
185		root := doc.(map[string]any)
186		entries := root["resources"].([]any)
187		resources := make([]planResource, 0, len(entries))
188		for _, entry := range entries {
189			obj := entry.(map[string]any)
190			var deps []string
191			if raw, ok := obj["dependsOn"].([]any); ok {
192				for _, el := range raw {
193					deps = append(deps, el.(string))
194				}
195			}
196			resources = append(resources, planResource{
197				address:    obj["address"].(string),
198				typ:        obj["type"].(string),
199				properties: obj["properties"].(map[string]any),
200				dependsOn:  deps,
201			})
202		}
203		return resources
204	}
205	
206	// checkPriorState validates the priorState document: an object with a
207	// resources array whose entries have a non-empty unique address, a non-empty
208	// type, a properties object, and an optional dependsOn. State types are not
209	// checked against the configuration's resource types. Shape problems are
210	// reported as invalid_plan_request and suppress dependency interpretation;
211	// dependency problems reuse the configuration dependency codes.
212	func checkPriorState(raw any) ([]planResource, []string, []validationError) {
213		const base = "/priorState"
214		var errs []validationError
215		add := func(code, message, path string) {
216			errs = append(errs, validationError{Code: code, Message: message, Path: path})
217		}
218	
219		obj, ok := raw.(map[string]any)
220		if !ok {
221			add(codeInvalidPlanRequest, `"priorState" must be an object`, base)
222			return nil, nil, errs
223		}
224		resourcesRaw, hasResources := obj["resources"]
225		if !hasResources {
226			add(codeInvalidPlanRequest, `missing required field "resources"`, base)
227			return nil, nil, errs
228		}
229		entries, ok := resourcesRaw.([]any)
230		if !ok {
231			add(codeInvalidPlanRequest, `"resources" must be an array`, base+"/resources")
232			return nil, nil, errs
233		}
234	
235		resources := make([]planResource, len(entries))
236		seenAddresses := map[string]bool{}
237		for i, entry := range entries {
238			entryPath := fmt.Sprintf("%s/resources/%d", base, i)
239			entryObj, ok := entry.(map[string]any)
240			if !ok {
241				add(codeInvalidPlanRequest, "state resource entry must be an object", entryPath)
242				continue
243			}
244			address, addressOK := planStringField(entryObj, "address", entryPath, add)
245			if addressOK {
246				if seenAddresses[address] {
247					add(codeDuplicateIdentifier, fmt.Sprintf("duplicate resource address %q", address), entryPath+"/address")
248					addressOK = false
249				} else {
250					seenAddresses[address] = true
251				}
252			}
253			typ, typeOK := planStringField(entryObj, "type", entryPath, add)
254			propsRaw, hasProps := entryObj["properties"]
255			props, propsOK := propsRaw.(map[string]any)
256			switch {
257			case !hasProps:
258				add(codeInvalidPlanRequest, `missing required field "properties"`, entryPath)
259			case !propsOK:
260				add(codeInvalidPlanRequest, `"properties" must be an object`, entryPath+"/properties")
261			}
262			if !addressOK || !typeOK || !hasProps || !propsOK {
263				continue
264			}
265			resources[i] = planResource{address: address, typ: typ, properties: props}
266		}
267		if len(errs) != 0 {
268			return nil, nil, errs
269		}
270	
271		addresses := make([]string, len(entries))
272		for i, resource := range resources {
273			addresses[i] = resource.address
274		}
275		dependsOn, order, depErrs := resolveDependencies(entries, addresses, base+"/resources")
276		if len(depErrs) != 0 {
277			return nil, nil, depErrs
278		}
279		for i := range resources {
280			resources[i].dependsOn = dependsOn[i]
281		}
282		return resources, order, nil
283	}
284	
285	// planStringField extracts a required non-empty string field of a prior
286	// state entry, reporting invalid_plan_request otherwise.
287	func planStringField(obj map[string]any, field, path string, add func(code, message, path string)) (string, bool) {
288		raw, ok := obj[field]
289		if !ok {
290			add(codeInvalidPlanRequest, fmt.Sprintf("missing required field %q", field), path)
291			return "", false
292		}
293		s, ok := raw.(string)
294		if !ok {
295			add(codeInvalidPlanRequest, fmt.Sprintf("%q must be a string", field), path+"/"+field)
296			return "", false
297		}
298		if s == "" {
299			add(codeInvalidPlanRequest, fmt.Sprintf("%q must not be empty", field), path+"/"+field)
300			return "", false
301		}
302		return s, true
303	}
304	
305	// computePlan aligns desired and prior resources by address. Deletes are
306	// listed in the reverse of the prior state's topological order; creates and
307	// updates follow the configuration's deterministic topological order.
308	// Resources equal on both sides are counted as noop and produce no change.
309	func computePlan(configResources []planResource, configOrder []string, stateResources []planResource, stateOrder []string) ([]planChange, planSummary) {
310		configByAddress := make(map[string]planResource, len(configResources))
311		for _, resource := range configResources {
312			configByAddress[resource.address] = resource
313		}
314		stateByAddress := make(map[string]planResource, len(stateResources))
315		for _, resource := range stateResources {
316			stateByAddress[resource.address] = resource
317		}
318	
319		actions := make(map[string]string, len(configResources)+len(stateResources))
320		var summary planSummary
321		for _, resource := range configResources {
322			prior, existed := stateByAddress[resource.address]
323			switch {
324			case !existed:
325				actions[resource.address] = "create"
326				summary.Create++
327			case resourceEqual(resource, prior):
328				summary.Noop++
329			default:
330				actions[resource.address] = "update"
331				summary.Update++
332			}
333		}
334		for _, resource := range stateResources {
335			if _, desired := configByAddress[resource.address]; !desired {
336				actions[resource.address] = "delete"
337				summary.Delete++
338			}
339		}
340	
341		changes := make([]planChange, 0, len(actions))
342		for i := len(stateOrder) - 1; i >= 0; i-- {
343			address := stateOrder[i]
344			if actions[address] != "delete" {
345				continue
346			}
347			before := snapshotOf(stateByAddress[address])
348			changes = append(changes, planChange{Address: address, Action: "delete", Before: &before})
349		}
350		for _, address := range configOrder {
351			action := actions[address]
352			if action != "create" && action != "update" {
353				continue
354			}
355			after := snapshotOf(configByAddress[address])
356			change := planChange{Address: address, Action: action, After: &after}
357			if action == "update" {
358				before := snapshotOf(stateByAddress[address])
359				change.Before = &before
360			}
361			changes = append(changes, change)
362		}
363		return changes, summary
364	}
365	
366	// snapshotOf renders a resource as a change snapshot with its dependencies
367	// normalized to ascending order.
368	func snapshotOf(resource planResource) planSnapshot {
369		deps := make([]string, len(resource.dependsOn))
370		copy(deps, resource.dependsOn)
371		sort.Strings(deps)
372		return planSnapshot{
373			Type:       resource.typ,
374			Properties: resource.properties,
375			DependsOn:  deps,
376		}
377	}
378	
379	// resourceEqual reports whether a desired and a prior resource are
380	// equivalent: same type, deeply equal properties, and equal dependency sets.
381	func resourceEqual(desired, prior planResource) bool {
382		if desired.typ != prior.typ {
383			return false
384		}
385		if !jsonValueEqual(desired.properties, prior.properties) {
386			return false
387		}
388		return stringSetEqual(desired.dependsOn, prior.dependsOn)
389	}
390	
391	// jsonValueEqual compares two decoded JSON values. Object key order is
392	// ignored, numbers compare by numeric value, and arrays are ordered.
393	func jsonValueEqual(a, b any) bool {
394		switch av := a.(type) {
395		case json.Number:
396			bv, ok := b.(json.Number)
397			return ok && jsonNumberEqual(av, bv)
398		case map[string]any:
399			bv, ok := b.(map[string]any)
400			if !ok || len(av) != len(bv) {
401				return false
402			}
403			for key, value := range av {
404				other, present := bv[key]
405				if !present || !jsonValueEqual(value, other) {
406					return false
407				}
408			}
409			return true
410		case []any:
411			bv, ok := b.([]any)
412			if !ok || len(av) != len(bv) {
413				return false
414			}
415			for i := range av {
416				if !jsonValueEqual(av[i], bv[i]) {
417					return false
418				}
419			}
420			return true
421		default:
422			return a == b
423		}
424	}
425	
426	// jsonNumberEqual compares two JSON number literals by numeric value, so
427	// 1, 1.0, and 1e0 are all equal.
428	func jsonNumberEqual(a, b json.Number) bool {
429		ra, okA := new(big.Rat).SetString(a.String())
430		rb, okB := new(big.Rat).SetString(b.String())
431		if okA && okB {
432			return ra.Cmp(rb) == 0
433		}
434		return a.String() == b.String()
435	}
436	
437	// stringSetEqual compares two duplicate-free string lists as sets.
438	func stringSetEqual(a, b []string) bool {
439		if len(a) != len(b) {
440			return false
441		}
442		counts := make(map[string]int, len(a))
443		for _, s := range a {
444			counts[s]++
445		}
446		for _, s := range b {
447			counts[s]--
448			if counts[s] < 0 {
449				return false
450			}
451		}
452		return true
453	}
454

