7	
8	// providerSource abstracts where the Providers and Observers for a run come
9	// from: either one injected Provider serving every resource type, or a
10	// registry dispatching each change and resource to the Provider registered
11	// for its type. The two modes differ in how routing failures are reported —
12	// the single-Provider mode keeps the baseline's exactly one pre-execution
13	// check, while the registry mode prechecks every change or resource and
14	// indexes the failure into the plan or the address-sorted resource list.
15	type providerSource interface {
16		// providerFor returns the Provider registered for typ.
17		providerFor(typ string) (Provider, bool)
18		// applyUnavailable builds the error reported when a change for typ at
19		// global plan index i cannot be routed to any Provider.
20		applyUnavailable(typ string, i int) validationError
21		// checkObserverPreLock runs the mode's Observer capability check that
22		// happens before the state lock is taken. It writes the response and
23		// returns false when the run must abort; message phrases the failure.
24		checkObserverPreLock(w http.ResponseWriter, message string) bool
25		// observerFor returns the Observer serving resource, or the precheck
26		// failure reported at ascending resource index i.
27		observerFor(resource planResource, i int) (Observer, *validationError)
28	}
