1	package server
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"math"
9		"net/http"
10		"os"
11		"path/filepath"
12		"strconv"
13		"sync"
14	)
15	
16	// Error codes reported by the state-file endpoints: the read-only GET and
17	// the locked, file-backed apply run.
18	const (
19		codeStateUnavailable    = "state_unavailable"
20		codeInvalidStateRequest = "invalid_state_request"
21		codeStateReadError      = "state_read_error"
22		codeStateWriteError     = "state_write_error"
23		codeStateLocked         = "state_locked"
24		codeStateConflict       = "state_conflict"
25	)
26	
27	// stateBackend serves the state-file endpoints for one canonicalized file
28	// path. The file holds a non-negative integer revision and a state document
29	// in the same resources shape the plan endpoints use; a missing file reads
30	// as revision 0 with no resources.
31	type stateBackend struct {
32		path string
33	}
34	
35	// newStateBackend canonicalizes path once so that handlers created
36	// separately for the same file share one lock slot.
37	func newStateBackend(path string) *stateBackend {
38		abs, err := filepath.Abs(path)
39		if err != nil {
40			abs = filepath.Clean(path)
41		}
42		if resolved, err := filepath.EvalSymlinks(abs); err == nil {
43			return &stateBackend{path: resolved}
44		}
45		// The file itself may not exist yet; resolve through its directory.
46		if resolvedDir, err := filepath.EvalSymlinks(filepath.Dir(abs)); err == nil {
47			return &stateBackend{path: filepath.Join(resolvedDir, filepath.Base(abs))}
48		}
49		return &stateBackend{path: abs}
50	}
51	
52	// stateLocks is the process-wide registry of state files currently being
53	// applied to, keyed by canonical path, so handlers created independently
54	// for the same path still exclude each other.
55	var stateLocks = struct {
56		mu   sync.Mutex
57		held map[string]bool
58	}{held: map[string]bool{}}
59	
60	// tryLockState takes the non-blocking exclusive lock for path. It returns
61	// ok=false immediately when another apply run holds the lock; otherwise the
62	// returned function releases it and must be called on every outcome.
63	func tryLockState(path string) (unlock func(), ok bool) {
64		stateLocks.mu.Lock()
65		defer stateLocks.mu.Unlock()
66		if stateLocks.held[path] {
67			return nil, false
68		}
69		stateLocks.held[path] = true
70		return func() {
71			stateLocks.mu.Lock()
72			delete(stateLocks.held, path)
73			stateLocks.mu.Unlock()
74		}, true
75	}
76	
77	// stateFileContents is the validated view of one state file.
78	type stateFileContents struct {
79		revision  int64
80		resources []planResource
81		order     []string
82	}
83	
84	// errInvalidStateContent marks a file that exists but does not hold a legal
85	// state document; both unreadable files and invalid content surface as
86	// state_read_error and never cause a rewrite.
87	var errInvalidStateContent = fmt.Errorf("invalid state file content")
88	
89	// readStateFile loads and validates the state file. A missing file is not
90	// an error: it reads as revision 0 with empty resources.
91	func readStateFile(path string) (stateFileContents, error) {
92		data, err := os.ReadFile(path)
93		if err != nil {
94			if os.IsNotExist(err) {
95				return stateFileContents{revision: 0}, nil
96			}
97			return stateFileContents{}, err
98		}
99	
100		dec := json.NewDecoder(bytes.NewReader(data))
101		dec.UseNumber()
102		var doc any
103		if err := dec.Decode(&doc); err != nil {
104			return stateFileContents{}, errInvalidStateContent
105		}
106		var trailing any
107		if err := dec.Decode(&trailing); err != io.EOF {
108			return stateFileContents{}, errInvalidStateContent
109		}
110	
111		obj, ok := doc.(map[string]any)
112		if !ok {
113			return stateFileContents{}, errInvalidStateContent
114		}
115		revision, ok := nonNegativeInt64(obj["revision"])
116		if !ok {
117			return stateFileContents{}, errInvalidStateContent
118		}
119		stateRaw, hasState := obj["state"]
120		if !hasState {
121			return stateFileContents{}, errInvalidStateContent
122		}
123		// The stored state document follows the same resources structure as the
124		// plan envelope's priorState, so it is validated by the same rules.
125		resources, order, errs := checkPriorState(stateRaw)
126		if len(errs) != 0 {
127			return stateFileContents{}, errInvalidStateContent
128		}
129		return stateFileContents{revision: revision, resources: resources, order: order}, nil
130	}
131	
132	// nonNegativeInt64 extracts a non-negative integer from a decoded JSON
133	// value. Whole-valued forms such as 1.0 or 1e2 count as integers, matching
134	// the configuration validator's notion of integer.
135	func nonNegativeInt64(v any) (int64, bool) {
136		n, ok := v.(json.Number)
137		if !ok {
138			return 0, false
139		}
140		s := n.String()
141		if i, err := strconv.ParseInt(s, 10, 64); err == nil {
142			return i, i >= 0
143		}
144		f, err := strconv.ParseFloat(s, 64)
145		if err != nil || math.IsInf(f, 0) || f != math.Trunc(f) || f < 0 || f >= 9223372036854775808.0 {
146			return 0, false
147		}
148		return int64(f), true
149	}
150	
151	// writeStateFile atomically replaces the state file: the new document is
152	// written to a sibling temporary file, synced, and renamed over the target,
153	// so a failed commit never leaves a half-written file and an existing
154	// original stays intact and readable.
155	func writeStateFile(path string, revision int64, state map[string]planResource) error {
156		doc := struct {
157			Revision int64          `json:"revision"`
158			State    *stateDocument `json:"state"`
159		}{Revision: revision, State: renderState(state)}
160		data, err := json.Marshal(doc)
161		if err != nil {
162			return err
163		}
164		data = append(data, '\n')
165	
166		tmp, err := os.CreateTemp(filepath.Dir(path), ".stackweaver-state-*")
167		if err != nil {
168			return err
169		}
170		tmpName := tmp.Name()
171		// Best-effort cleanup; after a successful rename this is a no-op.
172		defer os.Remove(tmpName)
173	
174		if info, err := os.Stat(path); err == nil {
175			// Preserve the existing file's permissions across the replacement.
176			_ = tmp.Chmod(info.Mode().Perm())
177		}
178		if _, err := tmp.Write(data); err != nil {
179			_ = tmp.Close()
180			return err
181		}
182		if err := tmp.Sync(); err != nil {
183			_ = tmp.Close()
184			return err
185		}
186		if err := tmp.Close(); err != nil {
187			return err
188		}
189		return os.Rename(tmpName, path)
190	}
191	
192	// handleStateUnavailable answers the state endpoints of handlers wired
193	// without a state file: every method gets 503 state_unavailable.
194	func handleStateUnavailable(w http.ResponseWriter, r *http.Request) {
195		w.Header().Set("Content-Type", "application/json; charset=utf-8")
196		writeValidation(w, http.StatusServiceUnavailable, []validationError{{
197			Code:    codeStateUnavailable,
198			Message: "state endpoints require a state file; use HandlerWithProviderAndStateFile",
199			Path:    "",
200		}})
201	}
202	
203	// stateResponse is the GET /v1/state payload.
204	type stateResponse struct {
205		Revision int64          `json:"revision"`
206		State    *stateDocument `json:"state"`
207	}
208	
209	// handleRead serves GET /v1/state: the current revision and the stored
210	// state document, normalized like an apply run's output state.
211	func (b *stateBackend) handleRead(w http.ResponseWriter, r *http.Request) {
212		w.Header().Set("Content-Type", "application/json; charset=utf-8")
213		if r.Method != http.MethodGet {
214			w.Header().Set("Allow", http.MethodGet)
215			w.WriteHeader(http.StatusMethodNotAllowed)
216			_ = json.NewEncoder(w).Encode(map[string]any{
217				"error": map[string]string{"code": "method_not_allowed"},
218			})
219			return
220		}
221	
222		current, err := readStateFile(b.path)
223		if err != nil {
224			writeValidation(w, http.StatusInternalServerError, []validationError{{
225				Code:    codeStateReadError,
226				Message: "state file cannot be read or does not hold a valid state document",
227				Path:    "",
228			}})
229			return
230		}
231	
232		w.WriteHeader(http.StatusOK)
233		_ = json.NewEncoder(w).Encode(stateResponse{
234			Revision: current.revision,
235			State:    renderState(seedState(current.resources)),
236		})
237	}
238	
239	// stateApplyResponse is the POST /v1/state/apply payload. Revision reports
240	// the file's revision after the run (unchanged when nothing was committed);
241	// CurrentRevision is set only on an expectedRevision conflict.
242	type stateApplyResponse struct {
243		Valid           bool              `json:"valid"`
244		Errors          []validationError `json:"errors"`
245		Applied         *[]planChange     `json:"applied,omitempty"`
246		Summary         planSummary       `json:"summary"`
247		State           *stateDocument    `json:"state,omitempty"`
248		Revision        *int64            `json:"revision,omitempty"`
249		CurrentRevision *int64            `json:"currentRevision,omitempty"`
250	}
251	
252	// handleApply serves POST /v1/state/apply: it plans the submitted
253	// configuration against the state file and executes under the file's
254	// non-blocking exclusive lock, committing the evolved state atomically.
255	func (b *stateBackend) handleApply(source providerSource) http.HandlerFunc {
256		return func(w http.ResponseWriter, r *http.Request) {
257			w.Header().Set("Content-Type", "application/json; charset=utf-8")
258			if r.Method != http.MethodPost {
259				rejectMethodNotAllowed(w)
260				return
261			}
262	
263			doc, ok := decodeConfigurationBody(w, r)
264			if !ok {
265				return
266			}
267			configRaw, expectedRevision, ok := checkStateApplyEnvelope(w, doc)
268			if !ok {
269				return
270			}
271	
272			// The configuration is validated exactly like the plan endpoint's,
273			// with findings rooted at /configuration, and planned from its
274			// variable-resolved view so the committed state holds literal
275			// properties only.
276			var errs []validationError
277			var configResources []planResource
278			var configOrder []string
279			if resolved, baseErrs := resolveConfiguration(configRaw); len(baseErrs) != 0 {
280				errs = appendPrefixedErrors(errs, baseErrs, "/configuration")
281			} else if order, depErrs := orderConfiguration(configRaw); len(depErrs) != 0 {
282				errs = appendPrefixedErrors(errs, depErrs, "/configuration")
283			} else {
284				configResources = configurationResources(resolved)
285				configOrder = order
286			}
287			if len(errs) != 0 {
288				sortValidationErrors(errs)
289				writeValidation(w, http.StatusUnprocessableEntity, errs)
290				return
291			}
292	
293			// The lock spans the run from read to commit; every outcome below
294			// releases it via the deferred unlock.
295			unlock, acquired := tryLockState(b.path)
296			if !acquired {
297				writeValidation(w, http.StatusConflict, []validationError{{
298					Code:    codeStateLocked,
299					Message: "state file is locked by another apply run",
300					Path:    "",
301				}})
302				return
303			}
304			defer unlock()
305	
306			current, err := readStateFile(b.path)
307			if err != nil {
308				writeValidation(w, http.StatusInternalServerError, []validationError{{
309					Code:    codeStateReadError,
310					Message: "state file cannot be read or does not hold a valid state document",
311					Path:    "",
312				}})
313				return
314			}
315	
316			if expectedRevision != nil && *expectedRevision != current.revision {
317				currentRevision := current.revision
318				w.WriteHeader(http.StatusConflict)
319				_ = json.NewEncoder(w).Encode(stateApplyResponse{
320					Valid: false,
321					Errors: []validationError{{
322						Code:    codeStateConflict,
323						Message: "expectedRevision does not match the current state revision",
324						Path:    "/expectedRevision",
325					}},
326					CurrentRevision: &currentRevision,
327				})
328				return
329			}
330	
331			changes, summary := computePlan(configResources, configOrder, current.resources, current.order)
332			state := seedState(current.resources)
333	
334			if len(changes) == 0 {
335				// An empty plan succeeds without a Provider and leaves the file
336				// and its revision untouched.
337				revision := current.revision
338				w.WriteHeader(http.StatusOK)
339				_ = json.NewEncoder(w).Encode(stateApplyResponse{
340					Valid:    true,
341					Errors:   []validationError{},
342					Applied:  &[]planChange{},
343					Summary:  summary,
344					State:    renderState(state),
345					Revision: &revision,
346				})
347				return
348			}
349	
350			// Precheck: every change must route to a registered Provider before
351			// anything executes. An unroutable change aborts the whole run
352			// without calling any Provider and leaves the file and its revision
353			// untouched.
354			providers := make([]Provider, len(changes))
355			for i, change := range changes {
356				typ := changeType(change)
357				provider, registered := source.providerFor(typ)
358				if !registered {
359					revision := current.revision
360					w.WriteHeader(http.StatusServiceUnavailable)
361					_ = json.NewEncoder(w).Encode(stateApplyResponse{
362						Valid:    false,
363						Errors:   []validationError{source.applyUnavailable(typ, i)},
364						Summary:  summary,
365						Revision: &revision,
366					})
367					return
368				}
369				providers[i] = provider
370			}
371	
372			applied := []planChange{}
373			var providerErr error
374			var failIndex int
375			// One fresh idempotency key per non-noop change of this top-level
376			// request; retries reuse a change's key under the held state lock.
377			keys := mintIdempotencyKeys(len(changes))
378			for i, change := range changes {
379				// executeChange applies the controlled retry policy serially;
380				// the lock stays held across every attempt. On failure the run
381				// stops immediately: later changes are skipped, earlier ones are
382				// not rolled back.
383				if err := executeChange(r.Context(), providers[i], change, keys[i]); err != nil {
384					providerErr = err
385					failIndex = i
386					break
387				}
388				applied = append(applied, change)
389				applyToState(state, change)
390			}
391	
392			// Commit when the run has something to persist: every change
393			// succeeded, or a Provider failure left at least one success behind.
394			// A first-change failure keeps the file untouched.
395			committed := false
396			if providerErr == nil || len(applied) > 0 {
397				if err := writeStateFile(b.path, current.revision+1, state); err != nil {
398					// The commit failed; the file keeps its old revision. The
399					// response still carries the executed changes and the state
400					// that could not be persisted.
401					revision := current.revision
402					w.WriteHeader(http.StatusInternalServerError)
403					_ = json.NewEncoder(w).Encode(stateApplyResponse{
404						Valid: false,
405						Errors: []validationError{{
406							Code:    codeStateWriteError,
407							Message: "state file could not be replaced atomically",
408							Path:    "",
409						}},
410						Applied:  &applied,
411						Summary:  summary,
412						State:    renderState(state),
413						Revision: &revision,
414					})
415					return
416				}
417				committed = true
418			}
419	
420			if providerErr != nil {
421				revision := current.revision
422				if committed {
423					// Partial state was persisted and takes exactly one version
424					// increment.
425					revision = current.revision + 1
426				}
427				w.WriteHeader(http.StatusBadGateway)
428				_ = json.NewEncoder(w).Encode(stateApplyResponse{
429					Valid:    false,
430					Errors:   []validationError{{Code: codeProviderError, Message: providerErr.Error(), Path: fmt.Sprintf("/changes/%d", failIndex)}},
431					Applied:  &applied,
432					Summary:  summary,
433					State:    renderState(state),
434					Revision: &revision,
435				})
436				return
437			}
438	
439			revision := current.revision + 1
440			w.WriteHeader(http.StatusOK)
441			_ = json.NewEncoder(w).Encode(stateApplyResponse{
442				Valid:    true,
443				Errors:   []validationError{},
444				Applied:  &applied,
445				Summary:  summary,
446				State:    renderState(state),
447				Revision: &revision,
448			})
449		}
450	}
451	
452	// checkStateApplyEnvelope validates the state-apply request envelope: a JSON
453	// object holding exactly the required configuration field and an optional
454	// expectedRevision that must be a non-negative integer. On failure it writes
455	// the 422 invalid_state_request response and returns ok=false.
456	func checkStateApplyEnvelope(w http.ResponseWriter, doc any) (configuration any, expectedRevision *int64, ok bool) {
457		var errs []validationError
458		add := func(code, message, path string) {
459			errs = append(errs, validationError{Code: code, Message: message, Path: path})
460		}
461	
462		root, isObject := doc.(map[string]any)
463		if !isObject {
464			add(codeInvalidStateRequest, "request body must be a JSON object", "")
465		} else {
466			for key := range root {
467				if key != "configuration" && key != "expectedRevision" {
468					add(codeInvalidStateRequest, fmt.Sprintf("unknown field %q", key), "/"+pointerEscape(key))
469				}
470			}
471			var hasConfig bool
472			configuration, hasConfig = root["configuration"]
473			if !hasConfig {
474				add(codeInvalidStateRequest, `missing required field "configuration"`, "")
475			}
476			if revRaw, has := root["expectedRevision"]; has {
477				if revision, valid := nonNegativeInt64(revRaw); valid {
478					expectedRevision = &revision
479				} else {
480					add(codeInvalidStateRequest, `"expectedRevision" must be a non-negative integer`, "/expectedRevision")
481				}
482			}
483		}
484	
485		if len(errs) != 0 {
486			sortValidationErrors(errs)
487			writeValidation(w, http.StatusUnprocessableEntity, errs)
488			return nil, nil, false
489		}
490		return configuration, expectedRevision, true
491	}
