1	package server
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"io"
7		"math"
8		"net/http"
9		"sort"
10		"strconv"
11		"strings"
12	)
13	
14	// Error codes reported by the configuration validator.
15	const (
16		codeInvalidJSON             = "invalid_json"
17		codeInvalidDocument         = "invalid_document"
18		codeDuplicateIdentifier     = "duplicate_identifier"
19		codeUnknownResourceType     = "unknown_resource_type"
20		codeTypeMismatch            = "type_mismatch"
21		codeMissingRequiredProperty = "missing_required_property"
22		codeUnexpectedProperty      = "unexpected_property"
23		codeUnknownDependency       = "unknown_dependency"
24		codeSelfDependency          = "self_dependency"
25		codeDuplicateDependency     = "duplicate_dependency"
26		codeDependencyCycle         = "dependency_cycle"
27	)
28	
29	// validationError is one machine-readable finding. Path is an RFC 6901 JSON
30	// Pointer into the submitted document.
31	type validationError struct {
32		Code    string `json:"code"`
33		Message string `json:"message"`
34		Path    string `json:"path"`
35	}
36	
37	type validateResponse struct {
38		Valid  bool              `json:"valid"`
39		Errors []validationError `json:"errors"`
40	}
41	
42	// handleValidateConfiguration validates a configuration document without
43	// creating or persisting anything.
44	func handleValidateConfiguration(w http.ResponseWriter, r *http.Request) {
45		w.Header().Set("Content-Type", "application/json; charset=utf-8")
46		if r.Method != http.MethodPost {
47			w.Header().Set("Allow", http.MethodPost)
48			w.WriteHeader(http.StatusMethodNotAllowed)
49			_ = json.NewEncoder(w).Encode(map[string]any{
50				"error": map[string]string{"code": "method_not_allowed"},
51			})
52			return
53		}
54	
55		doc, ok := decodeConfigurationBody(w, r)
56		if !ok {
57			return
58		}
59	
60		errs := validateConfiguration(doc)
61		sortValidationErrors(errs)
62		if len(errs) == 0 {
63			writeValidation(w, http.StatusOK, nil)
64			return
65		}
66		writeValidation(w, http.StatusUnprocessableEntity, errs)
67	}
68	
69	// decodeConfigurationBody reads the single JSON value expected from a
70	// configuration request body. It writes the shared 400 invalid_json response
71	// and returns ok=false when the body is empty, malformed, or trailing data.
72	func decodeConfigurationBody(w http.ResponseWriter, r *http.Request) (any, bool) {
73		dec := json.NewDecoder(r.Body)
74		dec.UseNumber()
75		var doc any
76		if err := dec.Decode(&doc); err != nil {
77			writeValidation(w, http.StatusBadRequest, []validationError{{
78				Code:    codeInvalidJSON,
79				Message: "request body is empty or is not valid JSON",
80				Path:    "",
81			}})
82			return nil, false
83		}
84		var trailing any
85		if err := dec.Decode(&trailing); err != io.EOF {
86			writeValidation(w, http.StatusBadRequest, []validationError{{
87				Code:    codeInvalidJSON,
88				Message: "request body must contain exactly one JSON value",
89				Path:    "",
90			}})
91			return nil, false
92		}
93		return doc, true
94	}
95	
96	// sortValidationErrors orders findings by JSON Pointer path, then by code.
97	func sortValidationErrors(errs []validationError) {
98		sort.SliceStable(errs, func(i, j int) bool {
99			if errs[i].Path != errs[j].Path {
100				return errs[i].Path < errs[j].Path
101			}
102			return errs[i].Code < errs[j].Code
103		})
104	}
105	
106	func writeValidation(w http.ResponseWriter, status int, errs []validationError) {
107		if errs == nil {
108			errs = []validationError{}
109		}
110		w.WriteHeader(status)
111		_ = json.NewEncoder(w).Encode(validateResponse{Valid: len(errs) == 0, Errors: errs})
112	}
113	
114	// pointerEscape escapes a single JSON Pointer path segment per RFC 6901.
115	func pointerEscape(s string) string {
116		s = strings.ReplaceAll(s, "~", "~0")
117		return strings.ReplaceAll(s, "/", "~1")
118	}
119	
120	// validateConfiguration checks a decoded document and returns every
121	// independently determinable problem, in discovery order.
122	func validateConfiguration(doc any) []validationError {
123		_, errs := resolveConfiguration(doc)
124		return errs
125	}
126	
127	// resolveConfiguration validates a decoded configuration document exactly
128	// like validateConfiguration and additionally returns the resolved view of
129	// the document: every variable reference inside resource properties is
130	// replaced by the referenced variable's literal value. A document naming
131	// neither variables nor variableValues is returned unchanged, so historical
132	// configurations keep their exact behavior. The resolved document is
133	// meaningful only when the returned error list is empty.
134	func resolveConfiguration(doc any) (any, []validationError) {
135		var errs []validationError
136		add := func(code, message, path string) {
137			errs = append(errs, validationError{Code: code, Message: message, Path: path})
138		}
139	
140		root, ok := doc.(map[string]any)
141		if !ok {
142			add(codeInvalidDocument, "document must be a JSON object", "")
143			return nil, errs
144		}
145		for key := range root {
146			if key != "resourceTypes" && key != "resources" && key != "variables" && key != "variableValues" {
147				add(codeInvalidDocument, fmt.Sprintf("unknown field %q", key), "/"+pointerEscape(key))
148			}
149		}
150	
151		typesRaw, hasTypes := root["resourceTypes"]
152		if !hasTypes {
153			add(codeInvalidDocument, `missing required field "resourceTypes"`, "")
154		}
155		resourcesRaw, hasResources := root["resources"]
156		if !hasResources {
157			add(codeInvalidDocument, `missing required field "resources"`, "")
158		}
159	
160		var typeEntries []any
161		if hasTypes {
162			arr, ok := typesRaw.([]any)
163			if !ok {
164				add(codeInvalidDocument, `"resourceTypes" must be an array`, "/resourceTypes")
165			} else {
166				typeEntries = arr
167			}
168		}
169		var resourceEntries []any
170		if hasResources {
171			arr, ok := resourcesRaw.([]any)
172			if !ok {
173				add(codeInvalidDocument, `"resources" must be an array`, "/resources")
174			} else {
175				resourceEntries = arr
176			}
177		}
178	
179		// declared holds every non-empty type name seen, even when its entry is
180		// invalid or a duplicate; usable holds only names with a valid, unique
181		// schema. Resources referencing a declared-but-unusable name are spared
182		// property-level errors.
183		declared := map[string]bool{}
184		usable := map[string]any{}
185		for i, entry := range typeEntries {
186			entryPath := fmt.Sprintf("/resourceTypes/%d", i)
187			obj, ok := entry.(map[string]any)
188			if !ok {
189				add(codeInvalidDocument, "resource type entry must be an object", entryPath)
190				continue
191			}
192			name, nameValid := identifierField(obj, "name", entryPath, add)
193			schemaRaw, hasSchema := obj["schema"]
194			schemaValid := false
195			if !hasSchema {
196				add(codeInvalidDocument, `missing required field "schema"`, entryPath)
197			} else {
198				before := len(errs)
199				validateSchema(schemaRaw, entryPath+"/schema", add)
200				schemaValid = len(errs) == before
201			}
202			if !nameValid {
203				continue
204			}
205			if declared[name] {
206				add(codeDuplicateIdentifier, fmt.Sprintf("duplicate resource type name %q", name), entryPath+"/name")
207				delete(usable, name)
208				continue
209			}
210			declared[name] = true
211			if schemaValid {
212				usable[name] = schemaRaw
213			}
214		}
215	
216		// The variable phase runs before property validation, dependency
217		// ordering, and diff computation: references inside resource properties
218		// are resolved against the declared variables and explicit values, and
219		// any problem it finds suppresses property validation, because
220		// unresolved properties cannot be checked against their schemas.
221		variableErrs := len(errs)
222		decls, variablesActive := checkVariableDeclarations(root, add)
223		resolved := doc
224		var resolvedEntries []any
225		if variablesActive {
226			resolvedEntries = make([]any, len(resourceEntries))
227			for i, entry := range resourceEntries {
228				obj, ok := entry.(map[string]any)
229				if !ok {
230					resolvedEntries[i] = entry
231					continue
232				}
233				props, ok := obj["properties"].(map[string]any)
234				if !ok {
235					resolvedEntries[i] = entry
236					continue
237				}
238				resolvedObj := make(map[string]any, len(obj))
239				for key, value := range obj {
240					resolvedObj[key] = value
241				}
242				resolvedObj["properties"] = resolveVariableReferences(props, fmt.Sprintf("/resources/%d/properties", i), decls, add)
243				resolvedEntries[i] = resolvedObj
244			}
245			resolvedRoot := make(map[string]any, len(root))
246			for key, value := range root {
247				resolvedRoot[key] = value
248			}
249			resolvedRoot["resources"] = resolvedEntries
250			resolved = resolvedRoot
251		}
252		variablesOK := len(errs) == variableErrs
253	
254		seenAddresses := map[string]bool{}
255		for i, entry := range resourceEntries {
256			entryPath := fmt.Sprintf("/resources/%d", i)
257			obj, ok := entry.(map[string]any)
258			if !ok {
259				add(codeInvalidDocument, "resource entry must be an object", entryPath)
260				continue
261			}
262			if address, ok := identifierField(obj, "address", entryPath, add); ok {
263				if seenAddresses[address] {
264					add(codeDuplicateIdentifier, fmt.Sprintf("duplicate resource address %q", address), entryPath+"/address")
265				} else {
266					seenAddresses[address] = true
267				}
268			}
269	
270			var schema any
271			schemaUsable := false
272			typeRaw, hasType := obj["type"]
273			typeName, typeIsString := typeRaw.(string)
274			switch {
275			case !hasType:
276				add(codeInvalidDocument, `missing required field "type"`, entryPath)
277			case !typeIsString:
278				add(codeInvalidDocument, `"type" must be a string`, entryPath+"/type")
279			case typeName == "":
280				add(codeInvalidDocument, `"type" must not be empty`, entryPath+"/type")
281			case !declared[typeName]:
282				add(codeUnknownResourceType, fmt.Sprintf("unknown resource type %q", typeName), entryPath+"/type")
283			default:
284				if s, ok := usable[typeName]; ok {
285					schema, schemaUsable = s, true
286				}
287			}
288	
289			propsRaw, hasProps := obj["properties"]
290			if !hasProps {
291				add(codeInvalidDocument, `missing required field "properties"`, entryPath)
292				continue
293			}
294			props, ok := propsRaw.(map[string]any)
295			if !ok {
296				add(codeInvalidDocument, `"properties" must be an object`, entryPath+"/properties")
297				continue
298			}
299			if schemaUsable && variablesOK {
300				// Properties are validated against their schema only after
301				// variable resolution has replaced every reference with its
302				// literal value.
303				validateValue(resolvedPropertiesOf(resolvedEntries, i, props), schema, entryPath+"/properties", add)
304			}
305		}
306	
307		return resolved, errs
308	}
309	
310	// resolvedPropertiesOf returns the variable-resolved properties of resource
311	// entry i, falling back to the original properties when the variable phase
312	// was inactive for the document.
313	func resolvedPropertiesOf(resolvedEntries []any, i int, props map[string]any) map[string]any {
314		if resolvedEntries == nil {
315			return props
316		}
317		if obj, ok := resolvedEntries[i].(map[string]any); ok {
318			if resolved, ok := obj["properties"].(map[string]any); ok {
319				return resolved
320			}
321		}
322		return props
323	}
324	
325	// identifierField extracts a required non-empty string field, reporting
326	// invalid_document for a missing, non-string, or empty value.
327	func identifierField(obj map[string]any, field, path string, add func(code, message, path string)) (string, bool) {
328		raw, ok := obj[field]
329		if !ok {
330			add(codeInvalidDocument, fmt.Sprintf("missing required field %q", field), path)
331			return "", false
332		}
333		s, ok := raw.(string)
334		if !ok {
335			add(codeInvalidDocument, fmt.Sprintf("%q must be a string", field), path+"/"+field)
336			return "", false
337		}
338		if s == "" {
339			add(codeInvalidDocument, fmt.Sprintf("%q must not be empty", field), path+"/"+field)
340			return "", false
341		}
342		return s, true
343	}
344	
345	// validateSchema checks the structural legality of a schema, recursing into
346	// array items and object properties.
347	func validateSchema(schema any, path string, add func(code, message, path string)) {
348		obj, ok := schema.(map[string]any)
349		if !ok {
350			add(codeInvalidDocument, "schema must be an object", path)
351			return
352		}
353		typeRaw, hasType := obj["type"]
354		typeName, isString := typeRaw.(string)
355		if !hasType {
356			add(codeInvalidDocument, `missing required field "type"`, path)
357			return
358		}
359		if !isString {
360			add(codeInvalidDocument, `"type" must be a string`, path+"/type")
361			return
362		}
363		switch typeName {
364		case "string", "integer", "number", "boolean":
365		case "array":
366			items, has := obj["items"]
367			if !has {
368				add(codeInvalidDocument, `array schema requires "items"`, path)
369				return
370			}
371			validateSchema(items, path+"/items", add)
372		case "object":
373			if propsRaw, has := obj["properties"]; has {
374				props, ok := propsRaw.(map[string]any)
375				if !ok {
376					add(codeInvalidDocument, `"properties" must be an object`, path+"/properties")
377				} else {
378					names := make([]string, 0, len(props))
379					for name := range props {
380						names = append(names, name)
381					}
382					sort.Strings(names)
383					for _, name := range names {
384						validateSchema(props[name], path+"/properties/"+pointerEscape(name), add)
385					}
386				}
387			}
388			if reqRaw, has := obj["required"]; has {
389				req, ok := reqRaw.([]any)
390				if !ok {
391					add(codeInvalidDocument, `"required" must be an array of strings`, path+"/required")
392				} else {
393					for j, entry := range req {
394						if _, ok := entry.(string); !ok {
395							add(codeInvalidDocument, `"required" entries must be strings`, fmt.Sprintf("%s/required/%d", path, j))
396						}
397					}
398				}
399			}
400			if apRaw, has := obj["additionalProperties"]; has {
401				if _, ok := apRaw.(bool); !ok {
402					add(codeInvalidDocument, `"additionalProperties" must be a boolean`, path+"/additionalProperties")
403				}
404			}
405		default:
406			add(codeInvalidDocument, fmt.Sprintf("unknown schema type %q", typeName), path+"/type")
407		}
408	}
409	
410	// validateValue checks a value against an already-validated schema.
411	func validateValue(value, schema any, path string, add func(code, message, path string)) {
412		obj, ok := schema.(map[string]any)
413		if !ok {
414			return
415		}
416		typeName, _ := obj["type"].(string)
417		switch typeName {
418		case "string":
419			if _, ok := value.(string); !ok {
420				add(codeTypeMismatch, fmt.Sprintf("expected string, got %s", jsonTypeName(value)), path)
421			}
422		case "boolean":
423			if _, ok := value.(bool); !ok {
424				add(codeTypeMismatch, fmt.Sprintf("expected boolean, got %s", jsonTypeName(value)), path)
425			}
426		case "integer":
427			n, ok := value.(json.Number)
428			if !ok || !isJSONInteger(n) {
429				add(codeTypeMismatch, fmt.Sprintf("expected integer, got %s", jsonTypeName(value)), path)
430			}
431		case "number":
432			if _, ok := value.(json.Number); !ok {
433				add(codeTypeMismatch, fmt.Sprintf("expected number, got %s", jsonTypeName(value)), path)
434			}
435		case "array":
436			arr, ok := value.([]any)
437			if !ok {
438				add(codeTypeMismatch, fmt.Sprintf("expected array, got %s", jsonTypeName(value)), path)
439				return
440			}
441			items := obj["items"]
442			for i, el := range arr {
443				validateValue(el, items, fmt.Sprintf("%s/%d", path, i), add)
444			}
445		case "object":
446			rec, ok := value.(map[string]any)
447			if !ok {
448				add(codeTypeMismatch, fmt.Sprintf("expected object, got %s", jsonTypeName(value)), path)
449				return
450			}
451			props, _ := obj["properties"].(map[string]any)
452			additional := false
453			if ap, ok := obj["additionalProperties"].(bool); ok {
454				additional = ap
455			}
456			seen := map[string]bool{}
457			if reqRaw, ok := obj["required"].([]any); ok {
458				for _, entry := range reqRaw {
459					name, ok := entry.(string)
460					if !ok || seen[name] {
461						continue
462					}
463					seen[name] = true
464					if _, present := rec[name]; !present {
465						add(codeMissingRequiredProperty, fmt.Sprintf("missing required property %q", name), path)
466					}
467				}
468			}
469			names := make([]string, 0, len(rec))
470			for name := range rec {
471				names = append(names, name)
472			}
473			sort.Strings(names)
474			for _, name := range names {
475				childPath := path + "/" + pointerEscape(name)
476				if sub, declared := props[name]; declared {
477					validateValue(rec[name], sub, childPath, add)
478				} else if !additional {
479					add(codeUnexpectedProperty, fmt.Sprintf("unexpected property %q", name), childPath)
480				}
481			}
482		}
483	}
484	
485	// isJSONInteger reports whether a JSON number literal denotes an integer.
486	// Whole-valued forms such as 1.0 or 1e2 count as integers; fractions do not.
487	func isJSONInteger(n json.Number) bool {
488		s := n.String()
489		if _, err := strconv.ParseInt(s, 10, 64); err == nil {
490			return true
491		}
492		f, err := strconv.ParseFloat(s, 64)
493		if err != nil {
494			return false
495		}
496		return !math.IsInf(f, 0) && f == math.Trunc(f)
497	}
498	
499	func jsonTypeName(v any) string {
500		switch v.(type) {
501		case nil:
502			return "null"
503		case bool:
504			return "boolean"
505		case json.Number:
506			return "number"
507		case string:
508			return "string"
509		case []any:
510			return "array"
511		case map[string]any:
512			return "object"
513		default:
514			return "value"
515		}
516	}
