1	package server
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"net/http"
9		"net/http/httptest"
10		"os"
11		"strings"
12		"sync"
13		"testing"
14	)
15	
16	// retryableErr is a RetryableError whose retryability is fixed at
17	// construction, matching the interface a Provider would return to ask the
18	// server to attempt the same change again.
19	type retryableErr struct {
20		msg       string
21		retryable bool
22	}
23	
24	func (e *retryableErr) Error() string { return e.msg }
25	func (e *retryableErr) Retryable() bool {
26		return e.retryable
27	}
28	
29	// wrappedRetryableErr wraps another error while still implementing
30	// RetryableError, exercising errors.As through an Unwrap chain.
31	type wrappedRetryableErr struct {
32		inner error
33	}
34	
35	func (e *wrappedRetryableErr) Error() string { return "wrapped: " + e.inner.Error() }
36	func (e *wrappedRetryableErr) Retryable() bool {
37		return true
38	}
39	func (e *wrappedRetryableErr) Unwrap() error { return e.inner }
40	
41	// scriptedRetryProvider fails per (address, attempt) with scripted errors and
42	// records every Apply call with its idempotency key and attempt number.
43	type scriptedRetryProvider struct {
44		mu       sync.Mutex
45		failures map[string]map[int]error // address -> 1-based attempts that fail
46		calls    []ChangeRequest
47	}
48	
49	func (p *scriptedRetryProvider) Apply(req ChangeRequest) error {
50		p.mu.Lock()
51		defer p.mu.Unlock()
52		p.calls = append(p.calls, req)
53		if byAttempt, ok := p.failures[req.Address]; ok {
54			if err, fail := byAttempt[req.Attempt]; fail {
55				return err
56			}
57		}
58		return nil
59	}
60	
61	func (p *scriptedRetryProvider) callsLocked() []ChangeRequest {
62		p.mu.Lock()
63		defer p.mu.Unlock()
64		out := make([]ChangeRequest, len(p.calls))
65		copy(out, p.calls)
66		return out
67	}
68	
69	func attemptsFor(calls []ChangeRequest, address string) []int {
70		var attempts []int
71		for _, c := range calls {
72			if c.Address == address {
73				attempts = append(attempts, c.Attempt)
74			}
75		}
76		return attempts
77	}
78	
79	func keysFor(calls []ChangeRequest, address string) []string {
80		var keys []string
81		for _, c := range calls {
82			if c.Address == address {
83				keys = append(keys, c.IdempotencyKey)
84			}
85		}
86		return keys
87	}
88	
89	// TestApplyRetrySucceedsOnThirdAttempt verifies the core retry contract: two
90	// retryable failures followed by success yield attempts 1, 2, 3 with one
91	// shared idempotency key, record the change once, and succeed overall.
92	func TestApplyRetrySucceedsOnThirdAttempt(t *testing.T) {
93		body := planBody(`[`+resEntry("a", `[]`)+`]`, `[]`)
94		transient := &retryableErr{msg: "transient", retryable: true}
95		provider := &scriptedRetryProvider{failures: map[string]map[int]error{
96			"a": {1: transient, 2: transient},
97		}}
98		res := doApply(t, HandlerWithProvider(provider), body, nil)
99		if res.status != http.StatusOK || !res.Valid {
100			t.Fatalf("status=%d valid=%v errors=%v", res.status, res.Valid, res.Errors)
101		}
102		calls := provider.callsLocked()
103		if got := attemptsFor(calls, "a"); fmt.Sprint(got) != "[1 2 3]" {
104			t.Fatalf("attempts = %v, want [1 2 3]", got)
105		}
106		keys := keysFor(calls, "a")
107		if len(keys) != 3 || keys[0] == "" || keys[0] != keys[1] || keys[1] != keys[2] {
108			t.Fatalf("idempotency keys = %v, want one non-empty key on all attempts", keys)
109		}
110		if res.Applied == nil || len(*res.Applied) != 1 || (*res.Applied)[0].Address != "a" {
111			t.Fatalf("applied = %v, want a recorded exactly once", res.Applied)
112		}
113	}
114	
115	// TestApplyRetryExhaustedReportsLastErrorAndIndex verifies that three
116	// retryable failures stop with 502 provider_error carrying the last error
117	// text and the change's global plan index.
118	func TestApplyRetryExhaustedReportsLastErrorAndIndex(t *testing.T) {
119		// b is created first (dependency), a second; a's index in the plan is 1.
120		body := planBody(`[`+resEntry("a", `["b"]`)+`,`+resEntry("b", `[]`)+`]`, `[]`)
121		provider := &scriptedRetryProvider{failures: map[string]map[int]error{
122			"a": {
123				1: &retryableErr{msg: "try 1", retryable: true},
124				2: &retryableErr{msg: "try 2", retryable: true},
125				3: &retryableErr{msg: "try 3", retryable: true},
126			},
127		}}
128		res := doApply(t, HandlerWithProvider(provider), body, nil)
129		if res.status != http.StatusBadGateway {
130			t.Fatalf("status = %d, want 502", res.status)
131		}
132		if len(res.Errors) != 1 {
133			t.Fatalf("errors = %v, want one", res.Errors)
134		}
135		e := res.Errors[0]
136		if e.Code != codeProviderError || e.Message != "try 3" || e.Path != "/changes/1" {
137			t.Fatalf("error = %+v, want last text at /changes/1", e)
138		}
139		calls := provider.callsLocked()
140		if got := attemptsFor(calls, "b"); fmt.Sprint(got) != "[1]" {
141			t.Fatalf("b attempts = %v, want single success", got)
142		}
143		if got := attemptsFor(calls, "a"); fmt.Sprint(got) != "[1 2 3]" {
144			t.Fatalf("a attempts = %v, want [1 2 3]", got)
145		}
146		// b applied once, a never recorded.
147		if res.Applied == nil || len(*res.Applied) != 1 || (*res.Applied)[0].Address != "b" {
148			t.Fatalf("applied = %v, want only b", res.Applied)
149		}
150	}
151	
152	// TestApplyNonRetryableErrorKeepsBaselineBehavior verifies that a plain error
153	// and a Retryable() == false error each stop after a single Apply call.
154	func TestApplyNonRetryableErrorKeepsBaselineBehavior(t *testing.T) {
155		body := planBody(`[`+resEntry("a", `[]`)+`]`, `[]`)
156	
157		t.Run("plain error", func(t *testing.T) {
158			provider := &scriptedRetryProvider{failures: map[string]map[int]error{
159				"a": {1: errors.New("plain boom")},
160			}}
161			res := doApply(t, HandlerWithProvider(provider), body, nil)
162			if res.status != http.StatusBadGateway || res.Errors[0].Message != "plain boom" {
163				t.Fatalf("unexpected result: %d %+v", res.status, res.Errors)
164			}
165			if got := attemptsFor(provider.callsLocked(), "a"); len(got) != 1 {
166				t.Fatalf("attempts = %v, want exactly 1", got)
167			}
168		})
169	
170		t.Run("explicitly non-retryable", func(t *testing.T) {
171			provider := &scriptedRetryProvider{failures: map[string]map[int]error{
172				"a": {1: &retryableErr{msg: "fatal", retryable: false}},
173			}}
174			res := doApply(t, HandlerWithProvider(provider), body, nil)
175			if res.status != http.StatusBadGateway || res.Errors[0].Message != "fatal" {
176				t.Fatalf("unexpected result: %d %+v", res.status, res.Errors)
177			}
178			if got := attemptsFor(provider.callsLocked(), "a"); len(got) != 1 {
179				t.Fatalf("attempts = %v, want exactly 1", got)
180			}
181		})
182	}
183	
184	// TestApplyRetryableThenNonRetryableStops verifies that a later attempt
185	// becoming non-retryable stops the run immediately without spending the
186	// remaining budget, reporting that attempt's error text.
187	func TestApplyRetryableThenNonRetryableStops(t *testing.T) {
188		body := planBody(`[`+resEntry("a", `[]`)+`]`, `[]`)
189		provider := &scriptedRetryProvider{failures: map[string]map[int]error{
190			"a": {
191				1: &retryableErr{msg: "transient", retryable: true},
192				2: errors.New("now fatal"),
193			},
194		}}
195		res := doApply(t, HandlerWithProvider(provider), body, nil)
196		if res.status != http.StatusBadGateway {
197			t.Fatalf("status = %d, want 502", res.status)
198		}
199		if e := res.Errors[0]; e.Message != "now fatal" || e.Path != "/changes/0" {
200			t.Fatalf("error = %+v", e)
201		}
202		if got := attemptsFor(provider.callsLocked(), "a"); fmt.Sprint(got) != "[1 2]" {
203			t.Fatalf("attempts = %v, want [1 2] — no third attempt", got)
204		}
205	}
206	
207	// TestApplyWrappedRetryableErrorIsRecognized verifies errors.As unwrapping:
208	// a wrapped error implementing RetryableError is still retried.
209	func TestApplyWrappedRetryableErrorIsRecognized(t *testing.T) {
210		body := planBody(`[`+resEntry("a", `[]`)+`]`, `[]`)
211		provider := &scriptedRetryProvider{failures: map[string]map[int]error{
212			"a": {1: &wrappedRetryableErr{inner: errors.New("x")}},
213		}}
214		res := doApply(t, HandlerWithProvider(provider), body, nil)
215		if res.status != http.StatusOK || !res.Valid {
216			t.Fatalf("status=%d errors=%v", res.status, res.Errors)
217		}
218		if got := attemptsFor(provider.callsLocked(), "a"); fmt.Sprint(got) != "[1 2]" {
219			t.Fatalf("attempts = %v, want wrapped retryable error retried once", got)
220		}
221	}
222	
223	// TestApplyIdempotencyKeysAreUniqueWithinRequestAndFreshAcrossRequests
224	// verifies the key allocation rules: non-empty, distinct per change within a
225	// request, reused across that change's attempts, and never reused by a later
226	// top-level request.
227	func TestApplyIdempotencyKeysAreUniqueWithinRequestAndFreshAcrossRequests(t *testing.T) {
228		body := planBody(`[`+resEntry("a", `[]`)+`,`+resEntry("b", `[]`)+`,`+resEntry("c", `[]`)+`]`, `[]`)
229	
230		provider := &scriptedRetryProvider{failures: map[string]map[int]error{
231			"b": {1: &retryableErr{msg: "t", retryable: true}}, // b retries once
232		}}
233		handler := HandlerWithProvider(provider)
234	
235		first := doApply(t, handler, body, nil)
236		if first.status != http.StatusOK {
237			t.Fatalf("first status = %d errors=%v", first.status, first.Errors)
238		}
239		second := doApply(t, handler, body, nil)
240		if second.status != http.StatusOK {
241			t.Fatalf("second status = %d errors=%v", second.status, second.Errors)
242		}
243	
244		calls := provider.callsLocked()
245		// Each request runs a#1, b#1, b#2 (b fails once), c#1: 4 calls apiece.
246		// The failures persist across requests, which is what lets us verify the
247		// retried change still gets a fresh key in the second request.
248		if len(calls) != 8 {
249			t.Fatalf("calls = %d, want 8 (a,b,b,c per request)", len(calls))
250		}
251		firstBatch, secondBatch := calls[:4], calls[4:]
252	
253		checkBatch := func(batch []ChangeRequest) map[string]string {
254			byAddress := map[string]string{}
255			seen := map[string]bool{}
256			for _, c := range batch {
257				if c.IdempotencyKey == "" {
258					t.Fatalf("empty idempotency key in call %+v", c)
259				}
260				if c.Attempt < 1 {
261					t.Fatalf("attempt = %d, want >= 1", c.Attempt)
262				}
263				if existing, ok := byAddress[c.Address]; ok {
264					if existing != c.IdempotencyKey {
265						t.Fatalf("address %s reused a different key across attempts: %q vs %q", c.Address, existing, c.IdempotencyKey)
266					}
267				} else {
268					if seen[c.IdempotencyKey] {
269						t.Fatalf("key %q shared by two changes in one request", c.IdempotencyKey)
270					}
271					seen[c.IdempotencyKey] = true
272					byAddress[c.Address] = c.IdempotencyKey
273				}
274			}
275			return byAddress
276		}
277	
278		firstKeys := checkBatch(firstBatch)
279		secondKeys := checkBatch(secondBatch)
280		for address, key := range firstKeys {
281			if key == secondKeys[address] {
282				t.Fatalf("address %s reused key %q across top-level requests", address, key)
283			}
284		}
285	}
286	
287	// TestApplyRetryDoesNotAdvanceToLaterChanges verifies that while a change is
288	// retrying, no later change is touched; subsequent changes execute only after
289	// the retried change succeeds.
290	func TestApplyRetryDoesNotAdvanceToLaterChanges(t *testing.T) {
291		body := planBody(`[`+resEntry("a", `[]`)+`,`+resEntry("b", `[]`)+`]`, `[]`)
292		provider := &scriptedRetryProvider{failures: map[string]map[int]error{
293			"a": {1: &retryableErr{msg: "t", retryable: true}},
294		}}
295		res := doApply(t, HandlerWithProvider(provider), body, nil)
296		if res.status != http.StatusOK {
297			t.Fatalf("status = %d", res.status)
298		}
299		calls := provider.callsLocked()
300		got := make([]string, len(calls))
301		for i, c := range calls {
302			got[i] = fmt.Sprintf("%s#%d", c.Address, c.Attempt)
303		}
304		if want := []string{"a#1", "a#2", "b#1"}; fmt.Sprint(got) != fmt.Sprint(want) {
305			t.Fatalf("call sequence = %v, want %v", got, want)
306		}
307	}
308	
309	// TestApplyRetryAbortsWhenContextEndsBeforeNextAttempt verifies that once the
310	// request context is over, a retryable failure is not followed by another
311	// Provider call; the response carries context.Err()'s text as provider_error.
312	func TestApplyRetryAbortsWhenContextEndsBeforeNextAttempt(t *testing.T) {
313		body := planBody(`[`+resEntry("a", `[]`)+`]`, `[]`)
314		ctx, cancel := context.WithCancel(context.Background())
315		provider := &cancelOnRetryProvider{cancel: cancel}
316		res := doApply(t, HandlerWithProvider(provider), body, ctx)
317		if res.status != http.StatusBadGateway {
318			t.Fatalf("status = %d, want 502", res.status)
319		}
320		if e := res.Errors[0]; e.Code != codeProviderError || e.Message != context.Canceled.Error() || e.Path != "/changes/0" {
321			t.Fatalf("error = %+v, want context cancellation text at /changes/0", e)
322		}
323		if len(provider.calls) != 1 {
324			t.Fatalf("provider calls = %d, want exactly 1 (no retry after context ended)", len(provider.calls))
325		}
326		if provider.calls[0].Attempt != 1 || provider.calls[0].IdempotencyKey == "" {
327			t.Fatalf("first call shape wrong: %+v", provider.calls[0])
328		}
