		`[]`, `true`)
	provider := &scriptedRetryProvider{failures: map[string]map[int]error{
		// c is created last and fails outright; b's compensation (its second
		// call for address b) fails retryably once.
		"c": {1: errors.New("create c failed")},
		"b": {2: &retryableErr{msg: "transient", retryable: true}},
	}}
	res := doApply(t, HandlerWithProvider(provider), body, nil)
	if res.status != http.StatusBadGateway {
		t.Fatalf("status = %d, want 502", res.status)
	}
	calls := provider.callsLocked()
	if got := providerCallsSummary(calls); got != "create:a|create:b|create:c|delete:c".replace("|delete:c", "")+"|delete:b|delete:b|delete:a" {
		t.Fatalf("calls = %q", got)
